import{_ as r,o as a,c as t,ag as o}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"🔬 科学快报 | 2026年8月5日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-05.md","filePath":"science-log/src/reconstructed/2026-08-05.md"}'),n={name:"science-log/src/reconstructed/2026-08-05.md"};function s(i,e,l,c,u,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="🔬-科学快报-2026年8月5日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月5日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月5日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月5日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。当日（2026-08-05，周三）ScienceDaily 仓库无对应简讯，故整期按日期区间重建。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424，<code>from-pub-date=until-pub-date=2026-08-05</code>）+ arXiv 日期区间 <code>[202608050000 TO 202608052359]</code>（cs.AI）；摘要与作者经 EuropePMC <code>resultType=core</code> 与 CrossRef <code>works/&lt;DOI&gt;</code> 核对 ｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="⚛️-双轨擦除量子比特的两比特纠缠门" tabindex="-1">⚛️ 双轨擦除量子比特的两比特纠缠门 <a class="header-anchor" href="#⚛️-双轨擦除量子比特的两比特纠缠门" aria-label="Permalink to &quot;⚛️ 双轨擦除量子比特的两比特纠缠门&quot;">​</a></h3><p><strong>An entangling gate for dual-rail erasure qubits</strong><em>Nature（2026-08-05，656: 47–53）</em></p><p>擦除量子比特（erasure qubit）的思路是人为造出&quot;误差层级&quot;：让最常见的噪声表现为可探测的泄漏（erasure），而不是难以纠正的 Pauli 错误，从而抬高纠错阈值、改善随码距的标度。难点在于门操作往往会破坏这个层级。D-Wave Quantum 团队的 73 位作者在超导微波腔里实现双轨腔量子比特的两比特纠缠门：门时长约 500 ns，单次门擦除率约 0.5%，残余 Pauli 错误低于 0.1%，且强烈偏向退相位——比特翻转在实际测量中处于 10⁻⁶ 量级、几乎不存在。作者用详细的表面码模拟说明，这种&quot;快 + 高擦除 + 极低比特翻转&quot;的组合能更快走向随规模迅速压低错误的纠错体系。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10822-y" target="_blank" rel="noreferrer">10.1038/s41586-026-10822-y</a></p><h3 id="☀️-用甲脒共晶实现热蒸发的钙钛矿-硅叠层电池" tabindex="-1">☀️ 用甲脒共晶实现热蒸发的钙钛矿/硅叠层电池 <a class="header-anchor" href="#☀️-用甲脒共晶实现热蒸发的钙钛矿-硅叠层电池" aria-label="Permalink to &quot;☀️ 用甲脒共晶实现热蒸发的钙钛矿/硅叠层电池&quot;">​</a></h3><p><strong>Thermally evaporated perovskite/silicon tandems via formamidinium eutectic</strong><em>Nature（2026-08-05，657: 385–392）</em></p><p>溶液法是目前高效钙钛矿/硅叠层的主流路线，但&quot;可工业化放大&quot;与&quot;长期可靠性&quot;难以兼得；热蒸发更贴近产线，却一直卡在甲脒碘（FAI）高温蒸发时的热分解上。作者合成了一种甲脒基共晶，把 FAI 的有效蒸发温度平均压低 36 °C、落到分解阈值以下，从而在不分解的前提下稳定蒸镀，得到结晶性更好、原子尺度组分更均匀的钙钛矿薄膜。器件结果：1 cm² 稳态效率 31.5%；在商用半片 G12 硅片上做出 200 cm² 大面积叠层、稳态效率 30%，面积从 1 cm² 放大到 200 cm² 的相对效率损失仅 3.99%（作者称是钙钛矿叠层面积放大损失的最低报道值）。85 °C/85% 相对湿度的湿热老化 2000 h 后仍保持初始效率的 95%，户外实际运行两个月功率损失可忽略。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10970-1" target="_blank" rel="noreferrer">10.1038/s41586-026-10970-1</a></p><h3 id="♻️-把废-pvc-升级再造为聚-α-烯烃润滑油" tabindex="-1">♻️ 把废 PVC 升级再造为聚 α-烯烃润滑油 <a class="header-anchor" href="#♻️-把废-pvc-升级再造为聚-α-烯烃润滑油" aria-label="Permalink to &quot;♻️ 把废 PVC 升级再造为聚 α-烯烃润滑油&quot;">​</a></h3><p><strong>Upcycling of polyvinyl chloride into polyalphaolefin lubricants</strong><em>Nature（2026-08-05，656: 376–382）</em></p><p>PVC 年产量约 6000 万吨，废弃后渗出的氯代烃与添加剂会污染土壤和地下水，而它含氯、易脱 HCl 的化学本性让常规机械/化学回收都很棘手。作者用 AlCl₃ 在 70 °C 的温和条件下让 PVC 同时发生脱氯、烷基化与断链，生成&quot;乙烯基来源的聚 α-烯烃&quot;（vPAO）——PVC 在这里不只是废料，而是充当各种链长 α-烯烃进行烷基化的模板，使产物主链上短支链很少，且无需现行 PAO 工艺必需的茂金属催化剂。所得润滑油摩尔质量与黏度可调：100 °C 运动黏度 KV₁₀₀ ≈ 14.9–26.3 cSt，摩擦系数 0.08–0.15，黏度指数最高 130。意义在于把最难的塑料品种直接变成高值产品，让回收在经济上自洽。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10867-z" target="_blank" rel="noreferrer">10.1038/s41586-026-10867-z</a></p><h3 id="🌊-流体动力相位牵引驱动精子鞭毛同步" tabindex="-1">🌊 流体动力相位牵引驱动精子鞭毛同步 <a class="header-anchor" href="#🌊-流体动力相位牵引驱动精子鞭毛同步" aria-label="Permalink to &quot;🌊 流体动力相位牵引驱动精子鞭毛同步&quot;">​</a></h3><p><strong>Hydrodynamic phase entrainment drives synchronization of sperm flagella</strong><em>PNAS（2026-08-05，123: e2614989123）</em></p><p>&quot;相邻鞭毛靠流体耦合就能同步，还是必须直接机械接触&quot;是这个领域长期悬而未决的争论：理论预测纯流体耦合足够，而自由游动的精子实验却指向接触必要。作者用微流控捕获阵列把成对精子头部固定、同时保留其自然摆动，从而在可控流体条件下长时间高精度测相位动力学；再用可容纳生物振子固有频差的 Adler 方程分析。结论是：头部固定条件下，纯流体耦合就足以驱动稳健的鞭毛同步；耦合强度在生理相关尺度内随鞭毛间距近似<strong>线性</strong>衰减；鞭毛相位涨落由<strong>低频有色噪声</strong>主导，这直接挑战了活性物质模型里通行的白噪声近似。作者进一步推导相位响应函数，把 Adler 方程的耦合项追溯到实测流场，使抽象的相位动力学落到流体力学基础上。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2614989123" target="_blank" rel="noreferrer">10.1073/pnas.2614989123</a></p><h3 id="🧠-杏仁核星形胶质细胞的初级纤毛参与应激行为" tabindex="-1">🧠 杏仁核星形胶质细胞的初级纤毛参与应激行为 <a class="header-anchor" href="#🧠-杏仁核星形胶质细胞的初级纤毛参与应激行为" aria-label="Permalink to &quot;🧠 杏仁核星形胶质细胞的初级纤毛参与应激行为&quot;">​</a></h3><p><strong>Amygdala astrocyte primary cilium mechanisms contribute to stress behaviours</strong><em>Nature（2026-08-05，657: 455–468）</em></p><p>不良生活事件如何转成持续的行为改变，仍是未解问题。作者把镜头对准杏仁核星形胶质细胞的<strong>初级纤毛</strong>（primary cilium）——一个把 GPCR 信号汇聚起来的细胞器。应激后杏仁核星形胶质细胞在蛋白与基因表达层面发生改变，纤毛相关分子表达下降，纤毛形态变短。用化学遗传学激活杏仁核星形胶质细胞 GPCR，或直接靶向天然的 1-磷酸鞘氨醇受体 1（S1PR1），可以恢复纤毛长度、纠正分子层面的改变并改善应激相关行为。作者还报告纤毛相关基因在人类样本中同样高表达。这给&quot;胶质细胞的结构性细胞器决定情绪行为&quot;提供了因果证据，也把 S1PR1 这类已上市靶点引向应激障碍。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10874-0" target="_blank" rel="noreferrer">10.1038/s41586-026-10874-0</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🧮-矩阵环带注意力-让-value-投影随上下文变化" tabindex="-1">🧮 矩阵环带注意力：让 value 投影随上下文变化 <a class="header-anchor" href="#🧮-矩阵环带注意力-让-value-投影随上下文变化" aria-label="Permalink to &quot;🧮 矩阵环带注意力：让 value 投影随上下文变化&quot;">​</a></h3><p><strong>Matrix Zonotopic Attention: A Context-Adaptive Value Projection for Set Transformers</strong><em>arXiv（2026-08-05）</em></p><p>多头注意力存在一个不对称：softmax 路由依赖输入，而 value 投影是<strong>与输入无关</strong>的线性映射，于是&quot;聚合值 → 输出&quot;这个逐样本算子对任何输入集合都一样。作者把它形式化为目标的&quot;变换自由度&quot;（TDOF）——精确表示一个目标算子所需的输入依赖方向数——并给出深度分离结论：上下文刚性注意力所需深度正比于目标的 TDOF，而单层、但 value 属于&quot;上下文自适应族&quot;的注意力就能表示同一目标。据此提出 MZAttn：用&quot;中心矩阵 + 若干被输入门控加权的生成矩阵&quot;构成的矩阵环带（matrix zonotope）族替代固定 value 投影；初始化时退化为标准多头注意力，保持置换等变，并可读出数据驱动的可达性解释。集合预测任务上的结果与 TDOF 预测一致——优势是<strong>选择性</strong>的：在高秩、稀疏组合式依赖输入集合的目标上出现，在聚合统计类目标上很小。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.05472" target="_blank" rel="noreferrer">2608.05472</a></p><h3 id="🔁-递归合成-把长程终端任务的数据成本压到-5-美分" tabindex="-1">🔁 递归合成：把长程终端任务的数据成本压到 5 美分 <a class="header-anchor" href="#🔁-递归合成-把长程终端任务的数据成本压到-5-美分" aria-label="Permalink to &quot;🔁 递归合成：把长程终端任务的数据成本压到 5 美分&quot;">​</a></h3><p><strong>Recursive Synthesis for Long-Horizon Terminal Tasks</strong><em>arXiv（2026-08-05）</em></p><p>长程终端智能体的训练数据极贵（每任务数百到数千美元），因为指令、环境、参考解、验证器必须互相一致；人工写不可扩展，直接用 LLM 生成又常破坏这些依赖。作者提出 RST：从已验证的种子任务出发，扩展参考解 → 按新工作流重对齐验证器与指令 → 在干净沙箱里验证 → 把通过的任务再当种子继续递归。15 轮递归产出 37,484 个任务，约 <strong>0.05 美元/任务</strong>。难度随轮次实质上升：参考解中位行数 67 → 374，执行命令中位数 40 → 244，DeepSeek-V4-Pro 的 pass@4 从 R1 的 90% 掉到 R15 的 2.5%。用拒绝采样得到的 Qwen3.5 轨迹做 SFT，可使 Qwen3.5-27B 与 122B-A10B 在 Terminal-Bench 2 / Hard 等基准上最多提升 10 个点。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.05466" target="_blank" rel="noreferrer">2608.05466</a></p><h3 id="🛠️-argus-长程任务的持久化智能体运行时" tabindex="-1">🛠️ Argus：长程任务的持久化智能体运行时 <a class="header-anchor" href="#🛠️-argus-长程任务的持久化智能体运行时" aria-label="Permalink to &quot;🛠️ Argus：长程任务的持久化智能体运行时&quot;">​</a></h3><p><strong>Argus: A General-Purpose Agentic Reasoning Runtime for Long-Horizon Tasks</strong><em>arXiv（2026-08-05）</em></p><p>长程推理要求运行时能&quot;证据支持就坚持、测量显示失败/隐藏约束/目标错设就转向&quot;。Argus 把 Manager / Planner / Engineer / Reviewer 四个角色放在<strong>持久项目状态</strong>上执行有界任务，并把稳定的用户意图与可操作目标、约束、验证标准分离；记忆、技能、流程、验证器、路由决策乃至被否决的路线，都必须经角色所属的评审（在可用时还经任务原生验证）才能入账。模型权重固定，自我进化全部发生在运行时状态与控制策略上。在七个 GPT-5.5 基准竞技场中，SWE-Bench Pro 约 78%（Direct Copilot 为 59%），总 token 用量为 1.41 倍；验证门控的自我进化后，成熟波次比启动波次少用 21% 求解输入 token、15% 活跃流程时间，期间记录 34 次验证器挽回与 22 次严格评审环挽救；AARRI-Bench 76.8%。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.05144" target="_blank" rel="noreferrer">2608.05144</a></p><h3 id="📚-octolong-用仓库级代码上下文做长上下文中训练" tabindex="-1">📚 OctoLong：用仓库级代码上下文做长上下文中训练 <a class="header-anchor" href="#📚-octolong-用仓库级代码上下文做长上下文中训练" aria-label="Permalink to &quot;📚 OctoLong：用仓库级代码上下文做长上下文中训练&quot;">​</a></h3><p><strong>OctoLong: Mid-Training On Cross-Repository Code Contexts Enhances Long-Context Modeling</strong><em>arXiv（2026-08-05）</em></p><p>现有长上下文语料以书籍、论文、代码仓库为主，既有限、又常缺乏真正的远距离依赖。OctoLong 是一条&quot;上下文工程&quot;流水线：接入 AST 解析器、语言服务器后端与包管理器，递归检索代码引用，从而构造出<strong>依赖密集</strong>、可达百万 token 的代码上下文。基于此训练 OctoLong-Instruct：从 600M 到 14B 的基座做起，在约 500 亿 token 混合语料（其中约 62 亿取自 OctoLong 代码上下文）上做上下文扩展中训练，再接约 100 亿 token 指令微调。消融显示：<strong>只用 OctoLong 数据替换 12%</strong> 的常规上下文扩展语料，就能在长程检索、长程状态跟踪、仓库级代码理解与下游智能体任务上明显提升，同时改善日常编码场景里的 API 使用；对比对象是 18 个强开源长上下文模型。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.05141" target="_blank" rel="noreferrer">2608.05141</a></p><h3 id="🎯-收敛点的扰动敏感性-无标注找出伪相关样本" tabindex="-1">🎯 收敛点的扰动敏感性：无标注找出伪相关样本 <a class="header-anchor" href="#🎯-收敛点的扰动敏感性-无标注找出伪相关样本" aria-label="Permalink to &quot;🎯 收敛点的扰动敏感性：无标注找出伪相关样本&quot;">​</a></h3><p><strong>Perturbation Sensitivity at Convergence: A Simple Signal for Identifying Spuriously Correlated Samples</strong><em>arXiv（2026-08-05）</em></p><p>数据里存在伪相关时，经验风险最小化能拿到很高的平均准确率，却在相关性不成立的子群上失效；现有无群体标注的识别方法都依赖训练早期信号，而&quot;在哪一轮介入&quot;本身是要用带群体标签的验证集调的超参。作者指出收敛之后仍有可用信号：此时 loss 已无法区分两类样本，但<strong>符合伪相关的样本被同一条共享规则分类</strong>，其余样本则靠逐个输入特有的配置被拟合，因而更脆弱——对收敛模型输入施加固定扰动，后者的预测翻转率远高于前者。整套流程只需每样本两次前向、全程无群体标注、无需早停轮次；用检出的样本重平衡训练，Waterbirds 最差群体准确率从 57.3% 提到 80.8%（使用真群体标签的上界为 85.8%）。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.05419" target="_blank" rel="noreferrer">2608.05419</a></p><hr><blockquote><p>📅 日期：2026-08-05 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇 🧾 期号：当日 ScienceDaily 无发布记录（第 21 期止于 2026-07-11），无法推定，故记（第 ? 期 · 事后重建版）</p></blockquote>',46)])])}const d=r(n,[["render",s]]);export{h as __pageData,d as default};
